    TEST_ASSERT_EQUAL(5226, at("cubic-bezier(0, 0, 0.52, 1.221)", 2799, 0));
    TEST_ASSERT_EQUAL(10115, at("cubic-bezier(0, 0, 0.52, 1.221)", 7843, 0));
